fun countdown(start: Int): String {
    var left = start
    val steps = mutableListOf<Int>()
    while (left > 0) {
        steps.add(left)
        left -= 1
    }
    return steps.joinToString(",")
}
fun main() {
    println(countdown(3))
    println("empty=${countdown(0).isEmpty()}")
}

