sealed interface ParseResult
data class Parsed(val value: Int) : ParseResult
data class Rejected(val reason: String) : ParseResult
fun parse(text: String): ParseResult =
    text.toIntOrNull()?.let { Parsed(it) } ?: Rejected("not an integer")
fun describe(result: ParseResult): String = when (result) {
    is Parsed -> "value=${result.value}"
    is Rejected -> "error=${result.reason}"
}
fun main() {
    println(describe(parse("12")))
    println(describe(parse("bad")))
}

