data class Task(val id: Int, val title: String, val done: Boolean = false)
fun addTask(tasks: List<Task>, id: Int, title: String): List<Task> {
    require(id > 0 && tasks.none { it.id == id })
    val clean = title.trim()
    require(clean.isNotEmpty())
    return tasks + Task(id, clean)
}
fun main() {
    val initial = listOf(Task(1, "Read"))
    val updated = addTask(initial, 2, " Code ")
    println(updated.joinToString(" | ") { "${it.id}:${it.title}" })
    println(initial.size)
    try { addTask(updated, 2, "Duplicate") }
    catch (error: IllegalArgumentException) { println("duplicate rejected") }
}

